			if !strings.Contains(filteredMsg, marker) {
				t.Fatalf("line %d error %q must contain %q", i+1, filteredMsg, marker)
			}
		}
		for _, marker := range markers[i].excludes {
			if strings.Contains(filteredMsg, marker) {
