		"--source-cidr", "192.0.2.0/24")
	if allFiltered.exitCode != 0 {
		t.Fatalf("an all-valid batch that misses the network must exit 0, got %d (stderr: %q)", allFiltered.exitCode, allFiltered.stderr)
